-				.registerAnimal(0.07, (field, location) -> new Bird(true, field, location))
-				.registerAnimal(0.07, (field, location) -> new Mouse(true, field, location))
-				.registerAnimal(0.07, (field, location) -> new Duck(true, field, location))
-				.registerAnimal(0.03, (field, location) -> new Wolf(true, field, location))
-				.registerAnimal(0.03, (field, location) -> new Bear(true, field, location));
+	/** Load the configuration file, falling back to built-in defaults if it is absent. */
+	static SimulationConfig loadConfig(Logger logger) {
+		Path path = Path.of(CONFIG_FILE);
+		try {
+			SimulationConfig config = SimulationConfig.load(path);
+			logger.log("Loaded configuration from " + path.toAbsolutePath());
+			return config;
+		} catch (IOException e) {
+			logger.log("No " + CONFIG_FILE + " found; using built-in defaults.");
+			return SimulationConfig.defaults();
+		}
